import React, { useState, useEffect } from 'react';
import { Camera, Check, Film, Music, Plus, Settings, Users } from 'lucide-react';
import { fetchTasks, fetchNotes, fetchMilestones, fetchSystemStatus, addNote as apiAddNote, updateNote, addTask, updateTask, deleteTask, updateMilestone } from './api';
import ShotList from './ShotList';


// Colors from the poster
const colors = {
  primary: '#f7abff',    // Pink background
  secondary: '#2f2a2f',  // Dark gray/black
  accent: '#3CDFFF',     // Cyan blue accent
  darkAccent: '#620f87', // Deep purple
  light: '#f9f9f9',      // White text
  midGray: '#797979',    // Mid gray
  successGreen: '#4ADE80'
};

function App() {
  const [activeTab, setActiveTab] = useState('overview');
  
  // Sample data
  const [tasks, setTasks] = useState([
    { id: 1, name: 'Character Modeling - Jax', category: 'Modeling', progress: 90, milestone: 'Pre-Production', completed: false },
    { id: 2, name: 'Rig Characters - Kiko', category: 'Rigging', progress: 75, milestone: 'Pre-Production', completed: false },
    { id: 3, name: 'Scene - Hiro Shop Interior', category: 'Modeling', progress: 90, milestone: 'Production', completed: false },
    { id: 4, name: 'Opening Theme Music', category: 'Audio', progress: 30, milestone: 'Post-Production', completed: false },
    { id: 5, name: 'Fight Scene Storyboard', category: 'Pre-production', progress: 100, milestone: 'Pre-Production', completed: true }
  ]);
  
  const [notes, setNotes] = useState([
    { id: 1, text: "Add more visual effects to Jax's guitar transformation", completed: false },
    { id: 2, text: "Adjust color grading in night scenes", completed: false },
    { id: 3, text: "Check Dr. White's facial animations", completed: true }
  ]);
  
  const [milestones, setMilestones] = useState([
    { id: 1, name: 'Pre-Production', completed: false, active: true, description: 'Character design, storyboarding, and initial setup', targetDate: '2025-06-01', order: 1 },
    { id: 2, name: 'Production', completed: false, active: false, description: 'Animation, modeling, and scene assembly', targetDate: '2025-09-01', order: 2 },
    { id: 3, name: 'Post-Production', completed: false, active: false, description: 'Rendering, effects, music, and final touches', targetDate: '2025-12-01', order: 3 }
  ]);

  // Initialize systemStatus with default values to prevent undefined errors
  const [systemStatus, setSystemStatus] = useState({
    storage: { total: 0, used: 0, percentage: 0 },
    backup: { last_backup: new Date().toISOString(), status: 'OK' },
    render_cache: { total: 0, used: 0, percentage: 0 }
  });

  // UI state
  const [newNote, setNewNote] = useState('');
  
  // Project statistics
  const projectStats = {
    scenes: { total: 24, completed: 16, label: 'Scenes Completed', icon: <Film className="w-6 h-6" /> },
    characters: { total: 6, completed: 4, label: 'Characters Rigged', icon: <Users className="w-6 h-6" /> },
    shots: { total: 300, completed: 120, label: 'Shots Animated', icon: <Camera className="w-6 h-6" /> },
    music: { total: 8, completed: 3, label: 'Music Tracks', icon: <Music className="w-6 h-6" /> }
  };
  
  // Load data from API
  useEffect(() => {
    const loadData = async () => {
      try {
        const fetchedTasks = await fetchTasks();
        if (fetchedTasks && fetchedTasks.length > 0) setTasks(fetchedTasks);
        
        const fetchedNotes = await fetchNotes();
        if (fetchedNotes && fetchedNotes.length > 0) setNotes(fetchedNotes);
        
        const fetchedMilestones = await fetchMilestones();
        if (fetchedMilestones && fetchedMilestones.length > 0) setMilestones(fetchedMilestones);
        
        const status = await fetchSystemStatus();
        if (status) {
          setSystemStatus(status);
        }
      } catch (error) {
        console.error("Error loading data:", error);
      }
    };
    
    loadData();
  }, []);
  
  // Handler functions
  const addNoteHandler = async () => {
    if (newNote.trim() !== '') {
      try {
        const noteData = { text: newNote, completed: false };
        const savedNote = await apiAddNote(noteData);
        setNotes([...notes, savedNote]);
        setNewNote('');
      } catch (error) {
        // Fallback to local state if API fails
        setNotes([...notes, { id: notes.length + 1, text: newNote, completed: false }]);
        setNewNote('');
        console.error("Failed to add note to API, using local state instead");
      }
    }
  };
  
  const toggleNoteComplete = async (id) => {
    try {
      const note = notes.find(n => n.id === id);
      const updatedNote = { ...note, completed: !note.completed };
      await updateNote(id, updatedNote);
      setNotes(notes.map(note => 
        note.id === id ? { ...note, completed: !note.completed } : note
      ));
    } catch (error) {
      // Fallback to local state if API fails
      setNotes(notes.map(note => 
        note.id === id ? { ...note, completed: !note.completed } : note
      ));
      console.error("Failed to update note in API, using local state instead");
    }
  };
  
  const toggleMilestone = async (id) => {
    try {
      await updateMilestone(id);
      setMilestones(milestones.map(milestone => 
        milestone.id === id ? { ...milestone, active: true } : { ...milestone, active: false }
      ));
    } catch (error) {
      // Fallback to local state if API fails
      setMilestones(milestones.map(milestone => 
        milestone.id === id ? { ...milestone, active: true } : { ...milestone, active: false }
      ));
      console.error("Failed to update milestone in API, using local state instead");
    }
  };
  
  const toggleTaskComplete = async (id) => {
    try {
      const task = tasks.find(t => t.id === id);
      const updatedTask = { ...task, completed: !task.completed };
      await updateTask(id, updatedTask);
      setTasks(tasks.map(task => 
        task.id === id ? { ...task, completed: !task.completed } : task
      ));
    } catch (error) {
      // Fallback to local state if API fails
      setTasks(tasks.map(task => 
        task.id === id ? { ...task, completed: !task.completed } : task
      ));
      console.error("Failed to update task in API, using local state instead");
    }
  };

  // Filter tasks based on active milestone
  const activeMilestoneName = milestones.find(m => m.active)?.name || 'Pre-Production';
  const filteredTasks = tasks.filter(task => task.milestone === activeMilestoneName);

  // Calculate milestone completion percentage
  const getMilestoneCompletion = (milestoneName) => {
    const milestoneTasks = tasks.filter(task => task.milestone === milestoneName);
    if (milestoneTasks.length === 0) return 0;
    
    const completedTasks = milestoneTasks.filter(task => task.completed).length;
    return Math.round((completedTasks / milestoneTasks.length) * 100);
  };

  // Calculate overall project progress for timeline
  const calculateProgress = () => {
    if (tasks.length === 0) return 0;
    
    const completedTasks = tasks.filter(task => task.completed).length;
    return Math.round((completedTasks / tasks.length) * 100);
  };

  // Format storage size for display
  const formatBytes = (bytes, decimals = 2) => {
    if (bytes === 0 || bytes === undefined) return '0 Bytes';
    
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    
    return parseFloat((bytes / Math.pow(k, i)).toFixed(decimals)) + ' ' + sizes[i];
  };

  return (
    <div className="min-h-screen" style={{ backgroundColor: colors.primary }}>
      <div className="max-w-6xl mx-auto p-8">
        <header className="mb-8 flex justify-between items-center">
          <div>
            <h1 className="text-4xl font-bold text-white mb-2">Melodic Justice</h1>
            <p className="text-gray-800">Animation Pipeline Dashboard</p>
          </div>
          <img 
            src="/logo192.png" 
            alt="Melodic Justice Logo"
            className="h-16 w-auto"
          />
        </header>

        {/* Tabs */}
        <div className="bg-gray-800 rounded-lg p-1 mb-6 flex flex-wrap">
          {['overview', 'milestones', 'tasks', 'shots', 'concepts', 'notes'].map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-4 py-2 rounded-md mr-1 mb-1 capitalize ${
                activeTab === tab 
                  ? 'bg-gray-700 text-white border-b-2' 
                  : 'text-gray-400 hover:text-white'
              }`}
              style={activeTab === tab ? { borderColor: colors.accent } : {}}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Overview Tab */}
        {activeTab === 'overview' && (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
              {Object.entries(projectStats).map(([key, stat]) => (
                <div key={key} className="rounded-lg p-4" style={{ backgroundColor: colors.secondary }}>
                  <div className="flex items-center justify-between pb-2">
                    <span className="text-sm font-medium text-gray-400">{stat.label}</span>
                    <div className="text-white">{stat.icon}</div>
                  </div>
                  <div className="text-2xl font-bold text-white mb-2">
                    {stat.completed}/{stat.total}
                  </div>
                  <div className="w-full bg-gray-700 h-2 rounded-full">
                    <div 
                      className="h-full rounded-full" 
                      style={{ 
                        width: `${(stat.completed / stat.total) * 100}%`,
                        backgroundColor: colors.accent
                      }}
                    ></div>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
              <div className="lg:col-span-2 rounded-lg p-4" style={{ backgroundColor: colors.secondary }}>
                <div className="mb-4">
                  <h2 className="text-xl font-bold text-white mb-4">Active Milestone: {activeMilestoneName}</h2>
                  
                  <div className="flex space-x-1 overflow-x-auto py-2 mb-4">
                    {milestones.sort((a, b) => a.order - b.order).map(milestone => (
                      <div 
                        key={milestone.id}
                        className="flex-shrink-0 relative"
                        style={{ width: '200px' }}
                      >
                        <button 
                          onClick={() => toggleMilestone(milestone.id)}
                          className={`w-full px-4 py-2 rounded-t flex items-center ${
                            milestone.active 
                              ? 'bg-purple-600 text-white' 
                              : milestone.completed
                                ? 'bg-gray-600 text-white'
                                : 'bg-gray-700 text-gray-300'
                          }`}
                        >
                          <span className="flex-grow truncate">{milestone.name}</span>
                          {milestone.completed && <Check className="h-4 w-4 ml-2 text-green-400" />}
                        </button>
                        <div 
                          className="h-1 w-full"
                          style={{ 
                            backgroundColor: milestone.completed 
                              ? colors.successGreen
                              : colors.accent,
                            opacity: milestone.active ? 1 : 0.5
                          }}
                        ></div>
                      </div>
                    ))}
                  </div>

                  <div className="relative h-8 bg-gray-700 rounded-full mb-6 overflow-hidden">
                    {milestones.sort((a, b) => a.order - b.order).map((milestone, index) => {
                      // Calculate position based on order
                      const totalMilestones = milestones.length;
                      const position = (index / totalMilestones) * 100;
                      const nextPosition = ((index + 1) / totalMilestones) * 100;
                      const width = nextPosition - position;
                      
                      return (
                        <div 
                          key={milestone.id}
                          className="absolute top-0 h-full flex items-center justify-center text-xs text-white px-2"
                          style={{ 
                            left: `${position}%`, 
                            width: `${width}%`,
                            backgroundColor: milestone.completed 
                              ? colors.successGreen 
                              : milestone.active 
                                ? colors.darkAccent 
                                : 'rgba(75, 75, 75, 0.5)',
                            borderRight: index < totalMilestones - 1 ? '1px solid rgba(255,255,255,0.2)' : 'none'
                          }}
                        >
                          <span className="truncate">{milestone.name}</span>
                        </div>
                      );
                    })}
                    
                    {/* Current progress indicator */}
                    <div 
                      className="absolute top-0 h-full w-1 bg-white"
                      style={{ 
                        left: `${calculateProgress()}%`,
                        boxShadow: '0 0 10px rgba(255,255,255,0.8)'
                      }}
                    ></div>
                  </div>
                </div>
                
                <h3 className="text-lg font-medium text-white mb-3">Current Tasks</h3>
                <div className="space-y-4">
                  {filteredTasks.length > 0 ? (
                    filteredTasks.map(task => (
                      <div key={task.id} className="p-4 rounded-lg bg-gray-800 flex items-start">
                        <div 
                          className="cursor-pointer mr-3 mt-1 flex-shrink-0"
                          onClick={() => toggleTaskComplete(task.id)}
                        >
                          {task.completed ? 
                            <Check className="h-5 w-5 text-green-500" /> : 
                            <div className="h-5 w-5 rounded-full border border-gray-500" />
                          }
                        </div>
                        <div className="flex-grow">
                          <div className="flex justify-between items-center mb-2">
                            <div>
                              <h3 className={`font-medium ${task.completed ? 'text-gray-400 line-through' : 'text-white'}`}>
                                {task.name}
                              </h3>
                              <span className="text-sm text-gray-400">{task.category}</span>
                            </div>
                            <span className="text-sm text-gray-400">{task.progress}%</span>
                          </div>
                          <div className="w-full bg-gray-700 h-2 rounded-full">
                            <div 
                              className="h-full rounded-full" 
                              style={{ 
                                width: `${task.progress}%`,
                                backgroundColor: task.completed ? colors.successGreen : colors.accent 
                              }}
                            ></div>
                          </div>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="p-4 rounded-lg bg-gray-800 text-gray-400 text-center">
                      No tasks for this milestone yet
                    </div>
                  )}
                </div>
              </div>

              <div className="rounded-lg p-4" style={{ backgroundColor: colors.secondary }}>
                <h2 className="text-xl font-bold text-white mb-4">Quick Notes</h2>
                <div className="space-y-2 mb-4">
                  {notes.slice(0, 5).map(note => (
                    <div 
                      key={note.id} 
                      className="flex items-start p-2 rounded"
                      style={{ backgroundColor: note.completed ? '#3a3a3a' : '#1a1a1a' }}
                    >
                      <div 
                        className="cursor-pointer mr-2 mt-1"
                        onClick={() => toggleNoteComplete(note.id)}
                      >
                        {note.completed ? 
                          <Check className="h-4 w-4 text-green-500" /> : 
                          <div className="h-4 w-4 rounded-full border border-gray-500" />
                        }
                      </div>
                      <p className={`text-sm ${note.completed ? 'text-gray-500 line-through' : 'text-gray-300'}`}>
                        {note.text}
                      </p>
                    </div>
                  ))}
                </div>
                <div className="flex">
                  <input 
                    value={newNote}
                    onChange={(e) => setNewNote(e.target.value)}
                    placeholder="Add a quick note..." 
                    className="flex-grow bg-gray-800 border-gray-700 p-2 rounded-l text-white"
                  />
                  <button 
                    onClick={addNoteHandler} 
                    className="px-3 py-2 rounded-r flex items-center justify-center"
                    style={{ backgroundColor: colors.accent }}
                  >
                    <Plus className="h-4 w-4 text-white" />
                  </button>
                </div>
              </div>
            </div>

            <div className="rounded-lg p-4" style={{ backgroundColor: colors.secondary }}>
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-bold text-white">System Status</h2>
                <Settings className="w-5 h-5 text-gray-400" />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="flex justify-between items-center p-4 rounded-lg bg-gray-800">
                  <div>
                    <h3 className="text-white font-medium">Storage</h3>
                    <span className="text-sm text-gray-400">
                      {systemStatus?.storage?.used !== undefined ? 
                        `${formatBytes(systemStatus.storage.used)} / ${formatBytes(systemStatus.storage.total)}` : 
                        "Loading..."}
                    </span>
                  </div>
                  <div className="w-24 bg-gray-700 h-2 rounded-full">
                    <div 
                      className="h-full rounded-full"
                      style={{ 
                        width: `${systemStatus?.storage?.percentage || 0}%`,
                        backgroundColor: colors.accent 
                      }}
                    ></div>
                  </div>
                </div>
                <div className="flex justify-between items-center p-4 rounded-lg bg-gray-800">
                  <div>
                    <h3 className="text-white font-medium">Backup Status</h3>
                    <span className="text-sm text-gray-400">
                      {systemStatus?.backup?.last_backup ? 
                        `Last: ${new Date(systemStatus.backup.last_backup).toLocaleTimeString()}` : 
                        "No recent backup"}
                    </span>
                  </div>
                  <div className="h-3 w-3 bg-green-500 rounded-full"></div>
                </div>
                <div className="flex justify-between items-center p-4 rounded-lg bg-gray-800">
                  <div>
                    <h3 className="text-white font-medium">Render Cache</h3>
                    <span className="text-sm text-gray-400">
                      {systemStatus?.render_cache?.used !== undefined ? 
                        `${formatBytes(systemStatus.render_cache.used)} / ${formatBytes(systemStatus.render_cache.total)}` : 
                        "Loading..."}
                    </span>
                  </div>
                  <div className="w-24 bg-gray-700 h-2 rounded-full">
                    <div 
                      className="h-full rounded-full"
                      style={{ 
                        width: `${systemStatus?.render_cache?.percentage || 0}%`,
                        backgroundColor: colors.accent 
                      }}
                    ></div>
                  </div>
                </div>
              </div>
            </div>
          </>
        )}

        {/* Placeholder content for other tabs */}
        {activeTab !== 'overview' && (
          <div className="rounded-lg p-8 text-center" style={{ backgroundColor: colors.secondary }}>
            <h2 className="text-xl font-bold text-white mb-4 capitalize">{activeTab} Dashboard</h2>
            <p className="text-gray-400">This tab will contain the {activeTab} management interface.</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
